  1→/**
  2→ * Acceptance tests.
  3→ *
  4→ * Each case is a rule that sounds reasonable and gets the verdict wrong: "some
  5→ * call returned 200", "it succeeded at some point", "it never failed", "there
  6→ * was no successful call so it failed".
  7→ */
  8→
  9→import { test } from "node:test";
 10→import assert from "node:assert/strict";
 11→
 12→import { verify, attempts, outcomeOfAttempt, PASS, FAIL, ERROR } from "./verify.mjs";
 13→
 14→import { TASK_MARKER } from "./verify.mjs";
 15→
 16→const TARGET_OK = "http://127.0.0.1:47318/skill-bridge/v3/skill/search";
 17→const TARGET_BAD = "http://10.244.7.19:8096/skill-bridge/v3/skill/search";
 18→const READ = "http://127.0.0.1:8096/skill-bridge/v3/skill/get-by-name";
 19→
 20→const OK_BODY = 'Stdout: {"code":0,"message":"ok","data":{"items":[]}}\nHTTP_CODE: 200';
 21→const TIMEOUT = "Exit code: 28\nStdout: \nStderr: curl: (28) Operation timed out after 75000 ms";
 22→
 23→/** The command the model wrote, as it appears in the tool call's arguments. */
 24→const cmdFor = (url, query) =>
 25→  JSON.stringify({ command: `curl -sSk -X POST ${url} -d '{"query":"${query}"}'` });
 26→
 27→/**
 28→ * A captured session. Each step is a call the model made, optionally with the
 29→ * result that came back — `body: null` means the result was never captured,
 30→ * which the attempt list has to survive.
 31→ */
 32→function session(steps) {
 33→  const messages = [{ role: "user", content: "do the task" }];
 34→  steps.forEach(({ url, body, query = TASK_MARKER }, i) => {
 35→    messages.push({
 36→      role: "assistant",
 37→      tool_calls: [{ id: `c${i}`, function: { name: "Bash", arguments: cmdFor(url, query) } }],
 38→    });
 39→    if (body !== null) {
 40→      messages.push({
 41→        role: "tool", tool_call_id: `c${i}`,
 42→        content: `Command: curl -sSk -X POST ${url} -d '{"query":"${query}"}'\n${body}`,
 43→      });
 44→    }
 45→  });
 46→  return [{
 47→    event: "http.request",
 48→    requestId: "req-1",
 49→    timestamp: "2026-09-05T12:00:00Z",
 50→    headers: { "x-conversation-id": "conv-1" },
 51→    body: { json: { messages } },
 52→  }];
 53→}
