 37→/**
 38→ * Tokenize into words and operators.
 39→ * @returns {Array<{type:"word", value:string, raw:string, literal:boolean} | {type:"op", value:string}>}
 40→ */
 41→export function tokenizeShell(cmd) {
 42→  const s = stripHeredocs(cmd ?? "");
 43→  const out = [];
 44→  let i = 0;
 45→  let cur = null;
 46→  const start = () => { if (!cur) cur = { value: "", raw: "", literal: true }; };
 47→  const push = () => { if (cur) out.push({ type: "word", ...cur }); cur = null; };
 48→  const op = (v) => { push(); out.push({ type: "op", value: v }); };
 49→
 50→  while (i < s.length) {
 51→    const ch = s[i], nx = s[i + 1];
 52→    if (ch === "\\" && nx === "\n") { i += 2; continue; }                       // continuation
 53→    if (ch === "'") {                                                            // single quotes: literal
 54→      start(); let j = s.indexOf("'", i + 1); if (j < 0) j = s.length;
 55→      cur.value += s.slice(i + 1, j); cur.raw += s.slice(i, j + 1); i = j + 1; continue;
 56→    }
 57→    if (ch === '"') {                                                            // double quotes: expansions inside
 58→      start(); i++; let v = "", raw = '"';
 59→      while (i < s.length && s[i] !== '"') {
 60→        if (s[i] === "\\" && i + 1 < s.length && '"\\$`\n'.includes(s[i + 1])) {
 61→          if (s[i + 1] !== "\n") v += s[i + 1];
 62→          raw += s.slice(i, i + 2); i += 2; continue;
 63→        }
 64→        if (s[i] === "$" || s[i] === "`") cur.literal = false;
 65→        v += s[i]; raw += s[i]; i++;
 66→      }
 67→      cur.value += v; cur.raw += raw + '"'; i++; continue;
 68→    }
 69→    if (ch === "\\") { start(); if (i + 1 < s.length) { cur.value += s[i + 1]; cur.raw += s.slice(i, i + 2); i += 2; } else i++; continue; }
 70→    if (ch === "#" && !cur) { const j = s.indexOf("\n", i); i = j < 0 ? s.length : j; continue; }   // comment
 71→    if (ch === "\n") { op("\n"); i++; continue; }
 72→    if (/\s/.test(ch)) { push(); i++; continue; }
 73→    if (ch === ";") { if (nx === ";") { op(";;"); i += 2; } else { op(";"); i++; } continue; }
 74→    if (ch === "&") {
 75→      // redirections `>&`, `&>`, `2>&1` are word text, not the background operator
 76→      if (cur && /[<>]$/.test(cur.value)) { cur.value += ch; cur.raw += ch; i++; continue; }
 77→      if (nx === ">") { start(); cur.value += "&>"; cur.raw += "&>"; i += 2; continue; }
 78→      if (nx === "&") { op("&&"); i += 2; } else { op("&"); i++; }
 79→      continue;
 80→    }
 81→    if (ch === "|") { if (nx === "|") { op("||"); i += 2; } else if (nx === "&") { op("|&"); i += 2; } else { op("|"); i++; } continue; }
 82→    if (ch === "(" || ch === ")") { if (cur && cur.value.endsWith("$")) { cur.value += ch; cur.raw += ch; i++; continue; } op(ch); i++; continue; }
 83→    if (ch === "$" && nx === "(") {                                              // $(…) kept whole, not literal
 84→      start(); cur.literal = false; let depth = 0, j = i + 1;
 85→      for (; j < s.length; j++) { if (s[j] === "(") depth++; else if (s[j] === ")") { depth--; if (depth === 0) break; } }
 86→      cur.value += s.slice(i, j + 1); cur.raw += s.slice(i, j + 1); i = j + 1; continue;
 87→    }
 88→    if (ch === "`") { start(); cur.literal = false; let j = s.indexOf("`", i + 1); if (j < 0) j = s.length; cur.value += s.slice(i, j + 1); cur.raw += s.slice(i, j + 1); i = j + 1; continue; }
 89→    start();
 90→    if (ch === "$") cur.literal = false;
 91→    cur.value += ch; cur.raw += ch; i++;
 92→  }
 93→  push();
 94→  return out;
 95→}
