121→/** Parse one curl word list into its request. */
122→function parseCurl(words) {
123→  const inv = { url: "", url_literal: true, host: "", port: "", path: "", method: null, headers: {}, body: null, body_literal: true, out_file: null, write_out: null, max_time: null, connect_timeout: null, flags: [] };
124→  const bodies = [];
125→  let urlWord = null;
126→  const take = (opt, value, literal) => {
127→    if (opt === "-X" || opt === "--request") inv.method = value.toUpperCase();
128→    else if (opt === "-H" || opt === "--header") { const k = value.indexOf(":"); if (k > 0) inv.headers[value.slice(0, k).trim().toLowerCase()] = value.slice(k + 1).trim(); }
129→    else if (DATA_OPTS.has(opt)) { bodies.push(value); if (!literal) inv.body_literal = false; if (opt === "--json") inv.headers["content-type"] ??= "application/json"; }
130→    else if (opt === "-o" || opt === "--output") inv.out_file = value;
131→    else if (opt === "-w" || opt === "--write-out") inv.write_out = value;
132→    else if (opt === "-m" || opt === "--max-time") inv.max_time = Number(value);
133→    else if (opt === "--connect-timeout") inv.connect_timeout = Number(value);
134→    else if (opt === "--url") { urlWord = { value, literal }; }
135→  };
136→  for (let i = 1; i < words.length; i++) {
137→    const w = words[i];
138→    const v = w.value;
139→    if (v.startsWith("--")) {
140→      const eq = v.indexOf("=");
141→      const name = eq > 0 ? v.slice(0, eq) : v;
142→      if (ARG_OPTS.has(name)) {
143→        if (eq > 0) take(name, v.slice(eq + 1), w.literal);
144→        else if (i + 1 < words.length) { take(name, words[i + 1].value, words[i + 1].literal); i++; }
145→      } else inv.flags.push(name);
146→      continue;
147→    }
148→    if (v.startsWith("-") && v.length > 1) {
149→      // short options, possibly combined (-sSk) or with an attached value (-o/tmp/x, -m20)
150→      let consumed = false;
151→      for (let k = 1; k < v.length; k++) {
152→        const c = v[k];
153→        if (SHORT_ARG.has(c)) {
154→          const rest = v.slice(k + 1);
155→          if (rest) take(`-${c}`, rest, w.literal);
156→          else if (i + 1 < words.length) { take(`-${c}`, words[i + 1].value, words[i + 1].literal); i++; }
157→          consumed = true; break;
158→        }
159→        if (c === "G") inv.method ??= "GET";
160→        inv.flags.push(`-${c}`);
161→      }
162→      if (consumed) continue;
163→      continue;
164→    }
165→    if (!urlWord) urlWord = { value: v, literal: w.literal };
166→  }
167→  if (urlWord) { inv.url = urlWord.value; inv.url_literal = urlWord.literal; Object.assign(inv, parseUrl(urlWord.value)); }
168→  if (bodies.length) inv.body = bodies.join("&");
169→  if (!inv.method) inv.method = bodies.length ? "POST" : "GET";
170→  return inv;
171→}
