106→test("a 200 carrying a service error is not a success", () => {
107→  // curl calls it success; the envelope refuses. The envelope is right.
108→  const r = outcomeOfAttempt('Stdout: {"code":40101,"message":"session not initialized"}\nHTTP_CODE: 200');
109→  assert.equal(r.ok, false);
