173→/**
174→ * Every curl invocation in the command, in shell order, with the structure
175→ * around it.
176→ *
177→ * @returns {Array<{url, url_literal, host, port, path, method, headers, body, body_literal, out_file, write_out, max_time,
178→ *   index, after_op, next_op, in_loop, conditional, background, piped, sequential, group}>}
179→ */
180→export function curlInvocations(cmd) {
181→  const tokens = tokenizeShell(cmd);
182→  const out = [];
183→  let loopDepth = 0, condDepth = 0, groupId = 0;
184→  const groups = [];          // stack of group ids for ( … )
185→  const groupInvs = new Map(); // group id -> invocations inside
186→  let prevOp = "";
187→  let cmdWords = [];
188→  let atStart = true;
189→
190→  const flush = (nextOp) => {
191→    // drop leading reserved words / assignments / wrappers, adjusting depth
192→    let ws = cmdWords;
193→    while (ws.length) {
194→      const w = ws[0].value;
195→      if (LOOP_OPEN.has(w)) { loopDepth++; ws = []; break; }          // loop header: not a command
196→      if (w === "done") { loopDepth = Math.max(0, loopDepth - 1); ws = ws.slice(1); continue; }
197→      if (COND_OPEN.has(w)) { condDepth++; ws = ws.slice(1); continue; } // `if curl …` — the curl is the condition
198→      if (w === "fi" || w === "esac") { condDepth = Math.max(0, condDepth - 1); ws = ws.slice(1); continue; }
199→      if (RESERVED.has(w)) { ws = ws.slice(1); continue; }
200→      if (/^[A-Za-z_][A-Za-z0-9_]*=/.test(w)) { ws = ws.slice(1); continue; }  // VAR=… prefix
201→      if (w === "command" || w === "exec" || w === "nice" || w === "nohup" || w === "env" || w === "sudo") { ws = ws.slice(1); continue; }
202→      if (w === "timeout" && ws.length > 2) { ws = ws.slice(2); continue; }
203→      break;
204→    }
205→    if (ws.length && (ws[0].value === "curl" || /(^|\/)curl$/.test(ws[0].value))) {
206→      const inv = parseCurl(ws);
207→      inv.index = out.length;
208→      inv.after_op = prevOp;
209→      inv.next_op = nextOp;
210→      inv.in_loop = loopDepth > 0;
211→      inv.conditional = condDepth > 0 || prevOp === "&&" || prevOp === "||";
212→      inv.background = nextOp === "&";
213→      inv.piped = nextOp === "|" || nextOp === "|&";
214→      inv.group = groups.length ? groups[groups.length - 1] : null;
215→      inv.sequential = !inv.background && !inv.in_loop;
216→      out.push(inv);
217→      if (inv.group !== null) (groupInvs.get(inv.group) ?? groupInvs.set(inv.group, []).get(inv.group)).push(inv);
218→    }
219→    cmdWords = [];
220→    atStart = true;
221→  };
222→
223→  for (let i = 0; i < tokens.length; i++) {
224→    const t = tokens[i];
225→    if (t.type === "word") { cmdWords.push(t); atStart = false; continue; }
226→    const v = t.value;
227→    if (v === "(") { flush(""); groups.push(++groupId); prevOp = ""; continue; }
228→    if (v === ")") {
229→      flush("");
230→      const g = groups.pop();
231→      const nextOp = tokens[i + 1]?.type === "op" ? tokens[i + 1].value : "";
232→      if (nextOp === "&") for (const inv of groupInvs.get(g) ?? []) { inv.background = true; inv.sequential = false; }
233→      prevOp = "";
234→      continue;
235→    }
236→    flush(v);
237→    prevOp = v;
238→  }
239→  flush("");
240→  return out;
241→}
