132→/** Enumeration endpoints hand back a list; they never retrieve one asset. */
133→export function isListingAction(action) {
134→  return /^(search|list|listing|list_[a-z_]+|search_[a-z_]+)$/.test(String(action ?? "").split(":").pop() ?? "");
135→}
